// ── EMBEDDED SOURCE FILES ─────────────────────────────────
// These are the actual file contents users copy into Apps Script.
// CODE_GS  = Code.gs  (backend — includes login/profile/access control)
// CODE_HTML = index.html (frontend UI)

const CODE_GS   = "// \u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557\n// \u2551          MailVault \u2014 Google Apps Script Backend              \u2551\n// \u2551  Runs entirely inside your Google Account. No Cloud setup.  \u2551\n// \u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d\n\nfunction doGet() {\n  return HtmlService.createHtmlOutputFromFile('index')\n    .setTitle('MailVault \u2014 Gmail Exporter')\n    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);\n}\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// getUserEmail()\n// Called on page load to show signed-in email in the hero pill.\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction getUserEmail() {\n  try {\n    return { email: Session.getActiveUser().getEmail() || '' };\n  } catch (e) {\n    return { email: '' };\n  }\n}\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// checkPermissions()\n// Probes whether the user still has valid OAuth permissions.\n// Called on page load \u2014 shows reconnect banner BEFORE fetch fails.\n//\n// Revocation is detected by:\n//   1. ScriptApp.getOAuthToken() throws/returns null  \u2192 revoked\n//   2. A minimal GmailApp.search() throws an auth error \u2192 revoked\n//\n// Returns:\n//   { status:'connected', email:string }\n//   { status:'revoked',   email:string, reconnectUrl:string }\n//   { status:'error',     email:string, message:string }\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction checkPermissions() {\n  var email = '';\n  try { email = Session.getActiveUser().getEmail() || ''; } catch(e) {}\n\n  // Step 1: probe OAuth token\n  var token = null;\n  try {\n    token = ScriptApp.getOAuthToken();\n  } catch (e) {\n    return { status:'revoked', email:email, reconnectUrl:_reconnectUrl() };\n  }\n  if (!token) {\n    return { status:'revoked', email:email, reconnectUrl:_reconnectUrl() };\n  }\n\n  // Step 2: probe Gmail scope\n  try {\n    GmailApp.search('label:inbox', 0, 1);\n  } catch (e) {\n    var m = (e.message || '').toLowerCase();\n    if (m.indexOf('authorization')!==-1 || m.indexOf('permission')!==-1 ||\n        m.indexOf('access')!=-1 || m.indexOf('scope')!==-1 ||\n        m.indexOf('token')!==-1 || m.indexOf('oauth')!==-1) {\n      return { status:'revoked', email:email, reconnectUrl:_reconnectUrl() };\n    }\n    // non-auth Gmail error \u2014 permissions fine\n  }\n\n  return { status:'connected', email:email };\n}\n\nfunction _reconnectUrl() {\n  try {\n    // Cache-busting param forces a fresh request so Apps Script\n    // re-evaluates auth state and re-prompts consent if needed.\n    return ScriptApp.getService().getUrl() + '?reconnect=1&t=' + Date.now();\n  } catch(e) { return ''; }\n}\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// fetchEmailsByDateRange()\n// Also detects mid-session revocation via errorType:'permissions_revoked'\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction fetchEmailsByDateRange(dateFrom, dateTo) {\n  try {\n    var after  = dateFrom.replace(/-/g, '/');\n    var before = _addOneDay(dateTo).replace(/-/g, '/');\n    var query  = 'after:' + after + ' before:' + before;\n\n    var emails  = [];\n    var start   = 0;\n    var perPage = 500;\n\n    while (true) {\n      var threads = GmailApp.search(query, start, perPage);\n      if (!threads || threads.length === 0) break;\n\n      threads.forEach(function(thread) {\n        thread.getMessages().forEach(function(msg) {\n          var msgDate = msg.getDate();\n          var from    = new Date(dateFrom + 'T00:00:00');\n          var to      = new Date(dateTo   + 'T23:59:59');\n          if (msgDate >= from && msgDate <= to) {\n            emails.push({\n              id:        msg.getId(),\n              threadId:  thread.getId(),\n              date:      Utilities.formatDate(msgDate, Session.getScriptTimeZone(), 'yyyy-MM-dd HH:mm:ss'),\n              from:      msg.getFrom(),\n              to:        msg.getTo(),\n              cc:        msg.getCc(),\n              bcc:       msg.getBcc(),\n              subject:   msg.getSubject() || '(no subject)',\n              snippet:   msg.getPlainBody().substring(0, 200).replace(/\\n/g, ' '),\n              labels:    thread.getLabels().map(function(l){ return l.getName(); }).join(', '),\n              isRead:    !msg.isUnread(),\n              isStarred: msg.isStarred(),\n              size:      msg.getRawContent().length,\n            });\n          }\n        });\n      });\n\n      if (threads.length < perPage) break;\n      start += perPage;\n    }\n\n    return { emails:emails, total:emails.length, error:null, errorType:null };\n\n  } catch (e) {\n    var msg = (e.message || '').toLowerCase();\n    var isAuth = msg.indexOf('authorization')!==-1 || msg.indexOf('permission')!==-1 ||\n                 msg.indexOf('access')!==-1 || msg.indexOf('oauth')!==-1;\n    return {\n      emails:[], total:0,\n      error: e.message,\n      errorType: isAuth ? 'permissions_revoked' : 'general'\n    };\n  }\n}\n\nfunction exportToSheet(emails, dateFrom, dateTo) {\n  try {\n    var sheetName = 'MailVault Export ' + dateFrom + (dateFrom !== dateTo ? ' to ' + dateTo : '');\n    var ss        = SpreadsheetApp.create(sheetName);\n\n    var emailSheet = ss.getActiveSheet();\n    emailSheet.setName('Emails');\n\n    var headers = ['#','Date','From','To','CC','BCC','Subject','Preview (200 chars)','Labels','Read','Starred','Size (bytes)','Message ID','Thread ID'];\n    emailSheet.appendRow(headers);\n    emailSheet.getRange(1,1,1,headers.length)\n      .setBackground('#0a0a0f').setFontColor('#00e5ff')\n      .setFontWeight('bold').setFontFamily('Courier New').setFontSize(9);\n\n    emails.forEach(function(e, i) {\n      emailSheet.appendRow([i+1,e.date,e.from,e.to,e.cc,e.bcc,e.subject,\n        e.snippet,e.labels,e.isRead?'Yes':'No',e.isStarred?'Yes':'No',\n        e.size,e.id,e.threadId]);\n    });\n\n    [40,160,220,220,160,160,300,400,140,60,70,90,160,160].forEach(function(w,i){\n      emailSheet.setColumnWidth(i+1, w);\n    });\n    emailSheet.setFrozenRows(1);\n    emailSheet.getRange(1,1,emailSheet.getLastRow(),headers.length).createFilter();\n\n    for (var r=2; r<=emails.length+1; r++) {\n      emailSheet.getRange(r,1,1,headers.length)\n        .setBackground(r%2===0?'#0f0f1a':'#13131f').setFontColor('#c8c8d8');\n    }\n\n    var summarySheet = ss.insertSheet('Summary');\n    [\n      ['MailVault \\u2014 Gmail Export Summary'],[],\n      ['Account',   Session.getActiveUser().getEmail()],\n      ['From',      dateFrom],['To', dateTo],\n      ['Total',     emails.length],\n      ['Read',      emails.filter(function(e){return  e.isRead;}).length],\n      ['Unread',    emails.filter(function(e){return !e.isRead;}).length],\n      ['Starred',   emails.filter(function(e){return  e.isStarred;}).length],\n      ['Generated', Utilities.formatDate(new Date(),Session.getScriptTimeZone(),'yyyy-MM-dd HH:mm:ss')],\n    ].forEach(function(row){ summarySheet.appendRow(row); });\n\n    summarySheet.getRange('A1').setFontSize(14).setFontWeight('bold').setFontColor('#00e5ff').setBackground('#0a0a0f');\n    summarySheet.getRange('A3:A10').setFontWeight('bold').setFontColor('#7c3aed');\n    summarySheet.getRange('B3:B10').setFontColor('#e8e8f0');\n    summarySheet.setColumnWidth(1,200); summarySheet.setColumnWidth(2,280);\n\n    var labelCounts={};\n    emails.forEach(function(e){\n      e.labels.split(', ').filter(Boolean).forEach(function(l){\n        labelCounts[l]=(labelCounts[l]||0)+1;\n      });\n    });\n    summarySheet.appendRow([]); summarySheet.appendRow(['Label','Count']);\n    summarySheet.getRange(summarySheet.getLastRow(),1,1,2)\n      .setFontWeight('bold').setFontColor('#00e5ff').setBackground('#0a0a0f');\n    Object.entries(labelCounts).sort(function(a,b){return b[1]-a[1];})\n      .forEach(function(entry){ summarySheet.appendRow(entry); });\n\n    ss.setActiveSheet(summarySheet); ss.moveActiveSheet(1);\n    return { url:ss.getUrl(), error:null };\n\n  } catch(e) {\n    return { url:null, error:e.message };\n  }\n}\n\nfunction _addOneDay(dateStr) {\n  var d = new Date(dateStr + 'T12:00:00');\n  d.setDate(d.getDate() + 1);\n  return d.toISOString().split('T')[0];\n}\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// getAppUrl()\n// Returns the deployed web app URL so the frontend can build the\n// Google logout redirect URL: accounts.google.com/logout?continue=<appUrl>\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction getAppUrl() {\n  try {\n    return ScriptApp.getService().getUrl();\n  } catch(e) {\n    return '';\n  }\n}\n"
const CODE_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>MailVault \u2014 Gmail Exporter</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=DM+Sans:wght@300;400;500;600&family=DM+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\n<style>\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}\n:root{\n  --night:#06040f;--deep:#0d0a1e;--card:#13102a;--card2:#1a163a;\n  --border:rgba(255,255,255,.08);--border2:rgba(255,255,255,.15);\n  --text:#f0eeff;--muted:rgba(240,238,255,.55);--faint:rgba(240,238,255,.28);\n  --em:#00e5a0;--em2:#00b87c;--vi:#a78bfa;--vi2:#7c3aed;\n  --ro:#fb7185;--am:#fbbf24;--bl:#60a5fa;\n}\nhtml{scroll-behavior:smooth}\nbody{font-family:'DM Sans',sans-serif;background:var(--night);color:var(--text);min-height:100vh;overflow-x:hidden}\n\n.bg-orbs{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}\n.orb{position:absolute;border-radius:50%;filter:blur(90px);opacity:.3;animation:drift 22s ease-in-out infinite}\n.orb1{width:640px;height:640px;background:radial-gradient(circle,#7c3aed,transparent 70%);top:-220px;left:-180px}\n.orb2{width:520px;height:520px;background:radial-gradient(circle,#00e5a0,transparent 70%);top:35%;right:-220px;animation-delay:-8s}\n.orb3{width:420px;height:420px;background:radial-gradient(circle,#fb7185,transparent 70%);bottom:-120px;left:25%;animation-delay:-15s}\n@keyframes drift{0%,100%{transform:translate(0,0) scale(1)}33%{transform:translate(28px,-36px) scale(1.04)}66%{transform:translate(-18px,28px) scale(.96)}}\n\n.wrap{position:relative;z-index:1;max-width:900px;margin:0 auto;padding:0 28px 100px}\n\n/* HERO */\n.hero{padding:80px 0 54px;text-align:center}\n.hero-pill{\n  display:inline-flex;align-items:center;gap:8px;\n  font-family:'DM Mono',monospace;font-size:.66rem;letter-spacing:.18em;text-transform:uppercase;\n  color:var(--em);background:rgba(0,229,160,.1);border:1px solid rgba(0,229,160,.28);\n  padding:6px 18px;border-radius:99px;margin-bottom:28px;animation:fdDown .6s ease both;\n}\n.hero-pill::before{content:'';width:6px;height:6px;background:var(--em);border-radius:50%;animation:pulse 2s infinite}\n@keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.35;transform:scale(.65)}}\n.hero h1{\n  font-family:'Playfair Display',serif;font-size:clamp(2.8rem,8vw,6.2rem);\n  font-weight:900;line-height:.93;letter-spacing:-.03em;margin-bottom:20px;\n  animation:fdDown .7s .1s ease both;\n}\n.grd{background:linear-gradient(135deg,var(--em) 0%,var(--vi) 55%,var(--ro) 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}\n.hero-sub{font-size:1.02rem;color:var(--muted);max-width:460px;margin:0 auto 34px;line-height:1.7;animation:fdDown .7s .2s ease both}\n.user-badge{\n  display:inline-flex;align-items:center;gap:9px;\n  background:rgba(255,255,255,.05);border:1px solid var(--border2);backdrop-filter:blur(14px);\n  padding:9px 20px;border-radius:99px;\n  font-family:'DM Mono',monospace;font-size:.73rem;color:var(--em);\n  animation:fdDown .7s .3s ease both;\n}\n.live-dot{width:7px;height:7px;background:var(--em);border-radius:50%;box-shadow:0 0 8px var(--em);animation:pulse 2s infinite;flex-shrink:0}\n#userPill{display:none}\n\n/* GLASS CARDS */\n.glass{\n  background:rgba(19,16,42,.72);border:1px solid var(--border);border-radius:20px;\n  backdrop-filter:blur(22px);padding:32px;margin-bottom:20px;\n  position:relative;overflow:hidden;\n  transition:border-color .3s,transform .2s,box-shadow .3s;\n  animation:fdUp .6s ease both;\n}\n.glass::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(255,255,255,.04) 0%,transparent 55%);pointer-events:none;border-radius:inherit}\n.glass:hover{border-color:var(--border2);transform:translateY(-2px);box-shadow:0 20px 56px rgba(0,0,0,.4)}\n.glass:nth-child(1){animation-delay:.08s}.glass:nth-child(2){animation-delay:.16s}.glass:nth-child(3){animation-delay:.24s}\n.stripe{position:absolute;top:0;left:0;right:0;height:2px;border-radius:20px 20px 0 0}\n.s-em{background:linear-gradient(90deg,var(--em),var(--vi))}.s-vi{background:linear-gradient(90deg,var(--vi),var(--bl))}.s-ro{background:linear-gradient(90deg,var(--ro),var(--am))}\n\n.chead{display:flex;align-items:center;gap:14px;margin-bottom:26px}\n.chip{font-family:'DM Mono',monospace;font-size:.59rem;letter-spacing:.14em;text-transform:uppercase;padding:4px 10px;border-radius:6px;font-weight:500;flex-shrink:0}\n.c-em{background:rgba(0,229,160,.14);color:var(--em);border:1px solid rgba(0,229,160,.28)}\n.c-vi{background:rgba(167,139,250,.14);color:var(--vi);border:1px solid rgba(167,139,250,.28)}\n.c-ro{background:rgba(251,113,133,.14);color:var(--ro);border:1px solid rgba(251,113,133,.28)}\n.ctitle{font-family:'Playfair Display',serif;font-size:1.22rem;font-weight:700}\n\n/* FORM */\n.field{margin-bottom:20px}.field:last-child{margin-bottom:0}\n.flbl{font-family:'DM Mono',monospace;font-size:.63rem;letter-spacing:.11em;text-transform:uppercase;color:var(--faint);margin-bottom:7px;display:block}\n.date-row{display:grid;grid-template-columns:1fr 22px 1fr;align-items:end;gap:10px}\n.darrow{text-align:center;color:var(--faint);font-size:1.1rem;padding-bottom:13px}\ninput[type=date],input[type=text],input[type=email],textarea{\n  width:100%;padding:12px 15px;\n  background:rgba(255,255,255,.05);border:1px solid var(--border2);border-radius:10px;\n  font-family:'DM Sans',sans-serif;font-size:.9rem;color:var(--text);\n  outline:none;transition:border-color .2s,box-shadow .2s,background .2s;-webkit-appearance:none;color-scheme:dark;\n}\ninput:focus,textarea:focus{border-color:var(--em);box-shadow:0 0 0 3px rgba(0,229,160,.14);background:rgba(0,229,160,.04)}\ninput::placeholder,textarea::placeholder{color:var(--faint)}\n.hint{font-family:'DM Mono',monospace;font-size:.62rem;color:var(--faint);margin-top:7px;line-height:1.5}\n\n/* BUTTONS */\n.brow{display:flex;gap:10px;flex-wrap:wrap;margin-top:4px}\n.btn{display:inline-flex;align-items:center;gap:8px;padding:12px 24px;font-family:'DM Sans',sans-serif;font-weight:600;font-size:.84rem;border:none;border-radius:10px;cursor:pointer;transition:all .2s;position:relative;overflow:hidden}\n.btn::after{content:'';position:absolute;inset:0;background:rgba(255,255,255,0);transition:background .2s}\n.btn:hover::after{background:rgba(255,255,255,.07)}\n.btn:active{transform:scale(.97)}.btn:disabled{opacity:.35;cursor:not-allowed;pointer-events:none}\n.btn-em{background:linear-gradient(135deg,var(--em2),var(--em));color:#06040f;font-weight:700;box-shadow:0 4px 22px rgba(0,229,160,.3)}\n.btn-em:hover{box-shadow:0 6px 30px rgba(0,229,160,.5);transform:translateY(-1px)}\n.btn-vi{background:linear-gradient(135deg,var(--vi2),var(--vi));color:#fff;box-shadow:0 4px 18px rgba(124,58,237,.3)}\n.btn-vi:hover{box-shadow:0 6px 26px rgba(124,58,237,.5);transform:translateY(-1px)}\n.btn-ghost{background:rgba(255,255,255,.06);color:var(--muted);border:1px solid var(--border2)}\n.btn-ghost:hover{background:rgba(255,255,255,.1);color:var(--text)}\n.btn-ro{background:linear-gradient(135deg,#e11d48,var(--ro));color:#fff;box-shadow:0 4px 18px rgba(251,113,133,.3)}\n.btn-ro:hover{box-shadow:0 6px 26px rgba(251,113,133,.5);transform:translateY(-1px)}\n.spin{width:13px;height:13px;border:2px solid rgba(255,255,255,.2);border-top-color:#fff;border-radius:50%;animation:rot .6s linear infinite;flex-shrink:0}\n.spin-dk{border:2px solid rgba(0,0,0,.15);border-top-color:rgba(0,0,0,.8)}\n@keyframes rot{to{transform:rotate(360deg)}}\n\n/* STATUS */\n.status{display:none;padding:13px 17px;border-radius:10px;font-size:.85rem;line-height:1.6;margin-top:18px;align-items:flex-start;gap:10px}\n.status.show{display:flex}\n.status.info{background:rgba(96,165,250,.1);border:1px solid rgba(96,165,250,.28);color:var(--bl)}\n.status.success{background:rgba(0,229,160,.08);border:1px solid rgba(0,229,160,.22);color:var(--em)}\n.status.error{background:rgba(251,113,133,.1);border:1px solid rgba(251,113,133,.28);color:var(--ro)}\n.status.warning{background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.28);color:var(--am)}\n.sico{flex-shrink:0}\n.prog-wrap{display:none;margin-top:18px}.prog-wrap.show{display:block}\n.prog-top{display:flex;justify-content:space-between;font-family:'DM Mono',monospace;font-size:.62rem;color:var(--faint);margin-bottom:7px}\n.prog-track{height:3px;background:rgba(255,255,255,.07);border-radius:99px;overflow:hidden}\n.prog-fill{height:100%;background:linear-gradient(90deg,var(--em2),var(--em));border-radius:99px;transition:width .35s ease;width:0%}\n\n/* EXPORT CARDS */\n.exp-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:22px}\n.ec{border:1px solid var(--border2);border-radius:14px;padding:20px 14px;cursor:pointer;transition:all .2s;text-align:center;background:rgba(255,255,255,.03);position:relative;overflow:hidden}\n.ec::before{content:'';position:absolute;inset:0;opacity:0;transition:opacity .2s;pointer-events:none}\n.ec.sel::before{opacity:1}\n.ec-csv::before{background:radial-gradient(circle at 50% 0%,rgba(0,229,160,.13),transparent 65%)}\n.ec-pdf::before{background:radial-gradient(circle at 50% 0%,rgba(251,113,133,.13),transparent 65%)}\n.ec-txt::before{background:radial-gradient(circle at 50% 0%,rgba(167,139,250,.13),transparent 65%)}\n.ec:hover{transform:translateY(-2px)}\n.ec.sel{border-color:var(--em);box-shadow:0 0 22px rgba(0,229,160,.14)}\n.ec.s-pdf{border-color:var(--ro)!important;box-shadow:0 0 22px rgba(251,113,133,.14)!important}\n.ec.s-txt{border-color:var(--vi)!important;box-shadow:0 0 22px rgba(167,139,250,.14)!important}\n.ec .ck{position:absolute;top:9px;right:9px;width:17px;height:17px;background:var(--em);border-radius:50%;color:#06040f;font-size:.58rem;display:none;align-items:center;justify-content:center;font-weight:800}\n.ec.sel .ck{display:flex}\n.eico{font-size:1.75rem;margin-bottom:7px;display:block}\n.ename{font-family:'DM Sans',sans-serif;font-weight:600;font-size:.76rem;color:var(--text);margin-bottom:3px}\n.edesc{font-size:.67rem;color:var(--faint);line-height:1.4}\n\n/* EMAIL TABLE */\n.es-wrap{display:none;margin-top:0}.es-wrap.show{display:block}\n.tbhead{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:12px}\n.tblbl{display:flex;flex-direction:column;gap:2px}\n.eyebrow{font-family:'DM Mono',monospace;font-size:.59rem;letter-spacing:.2em;text-transform:uppercase;color:var(--faint)}\n.tbtitle{font-family:'Playfair Display',serif;font-size:1.08rem;font-weight:700}\n.cnt-badge{display:inline-flex;align-items:center;gap:6px;background:rgba(0,229,160,.1);border:1px solid rgba(0,229,160,.22);padding:4px 12px;border-radius:99px;font-family:'DM Mono',monospace;font-size:.66rem;color:var(--em)}\n.sort-row{display:flex;align-items:center;gap:7px;flex-wrap:wrap}\n.slbl{font-family:'DM Mono',monospace;font-size:.59rem;color:var(--faint);letter-spacing:.1em;text-transform:uppercase}\n.sb{font-family:'DM Mono',monospace;font-size:.63rem;padding:5px 10px;border:1px solid var(--border2);background:rgba(255,255,255,.03);border-radius:7px;cursor:pointer;color:var(--muted);transition:all .15s;letter-spacing:.04em}\n.sb:hover{border-color:rgba(255,255,255,.22);color:var(--text);background:rgba(255,255,255,.07)}\n.sb.on{background:rgba(0,229,160,.12);color:var(--em);border-color:rgba(0,229,160,.38)}\n.twrap{border:1px solid var(--border);border-radius:14px;overflow:auto;max-height:450px;background:rgba(19,16,42,.5);backdrop-filter:blur(10px)}\ntable{width:100%;border-collapse:collapse;font-size:.79rem}\nthead th{padding:10px 13px;text-align:left;font-family:'DM Mono',monospace;font-size:.59rem;letter-spacing:.11em;text-transform:uppercase;color:var(--faint);background:rgba(255,255,255,.03);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:2;white-space:nowrap}\ntbody td{padding:10px 13px;border-bottom:1px solid rgba(255,255,255,.04);vertical-align:middle;color:var(--muted)}\ntbody tr:last-child td{border-bottom:none}\ntbody tr:hover td{background:rgba(255,255,255,.03);color:var(--text)}\n.td-n{color:var(--faint);font-family:'DM Mono',monospace;font-size:.6rem;width:30px}\n.td-s{font-weight:500;color:var(--text);max-width:215px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.td-f{max-width:145px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:'DM Mono',monospace;font-size:.63rem}\n.td-d{white-space:nowrap;font-family:'DM Mono',monospace;font-size:.63rem}\n.ud{display:inline-block;width:5px;height:5px;background:var(--em);border-radius:50%;margin-right:5px;vertical-align:middle;box-shadow:0 0 5px var(--em)}\n.ra{display:inline-flex;align-items:center;justify-content:center;width:27px;height:27px;border:1px solid var(--border2);background:rgba(255,255,255,.03);border-radius:7px;cursor:pointer;font-size:.76rem;transition:all .15s;margin-right:2px}\n.ra:hover{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.25);transform:scale(1.1)}\n.ra.del:hover{background:rgba(251,113,133,.2);border-color:rgba(251,113,133,.45)}\n\n/* MODAL */\n.mov{display:none;position:fixed;inset:0;background:rgba(6,4,15,.78);backdrop-filter:blur(10px);z-index:100;align-items:center;justify-content:center;padding:20px}\n.mov.open{display:flex}\n.modal{background:var(--card);border:1px solid var(--border2);border-radius:20px;width:100%;max-width:640px;max-height:88vh;display:flex;flex-direction:column;box-shadow:0 40px 100px rgba(0,0,0,.6);overflow:hidden;animation:mIn .25s ease}\n@keyframes mIn{from{opacity:0;transform:scale(.95) translateY(8px)}to{opacity:1;transform:none}}\n.mhd{padding:20px 24px 16px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;gap:12px;flex-shrink:0}\n.mhd-t{font-family:'Playfair Display',serif;font-size:1.08rem;font-weight:700}\n.mx{background:rgba(255,255,255,.06);border:none;color:var(--muted);width:29px;height:29px;border-radius:7px;cursor:pointer;font-size:.95rem;transition:all .15s}\n.mx:hover{background:rgba(251,113,133,.2);color:var(--ro)}\n.mbd{padding:20px 24px;overflow-y:auto;flex:1}\n.mft{padding:14px 24px;border-top:1px solid var(--border);display:flex;justify-content:flex-end;gap:8px;flex-shrink:0}\n.mf{margin-bottom:15px}.mf:last-child{margin-bottom:0}\n.mf label{font-family:'DM Mono',monospace;font-size:.6rem;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);margin-bottom:5px;display:block}\n.mv{font-size:.86rem;color:var(--text);padding:10px 13px;background:rgba(255,255,255,.04);border:1px solid var(--border);border-radius:8px;line-height:1.6;word-break:break-word}\n.mbtext{font-size:.84rem;color:var(--muted);line-height:1.7;white-space:pre-wrap;max-height:190px;overflow-y:auto;padding:11px 13px;background:rgba(255,255,255,.03);border:1px solid var(--border);border-radius:8px}\n.m2{display:grid;grid-template-columns:1fr 1fr;gap:11px}\n\n/* TOAST */\n.toast{position:fixed;bottom:26px;right:26px;z-index:200;padding:11px 20px;border-radius:12px;font-family:'DM Sans',sans-serif;font-size:.81rem;font-weight:600;box-shadow:0 12px 36px rgba(0,0,0,.4);transform:translateY(80px);opacity:0;transition:all .3s cubic-bezier(.34,1.56,.64,1);pointer-events:none}\n.toast.show{transform:translateY(0);opacity:1}\n.toast.ok{background:linear-gradient(135deg,var(--em2),var(--em));color:#06040f}\n.toast.err{background:linear-gradient(135deg,#e11d48,var(--ro));color:#fff}\n.toast.nn{background:var(--card2);border:1px solid var(--border2);color:var(--text)}\n\n/* FOOTER */\n.sfooter{margin-top:60px;padding:22px 0;border-top:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px}\n.fbrand{font-family:'Playfair Display',serif;font-weight:700;font-size:1rem;color:var(--text)}\n.fbrand span{color:var(--em)}\n.fmeta{font-family:'DM Mono',monospace;font-size:.6rem;color:var(--faint);line-height:1.7;text-align:right}\n\n@keyframes fdDown{from{opacity:0;transform:translateY(-14px)}to{opacity:1;transform:none}}\n@keyframes fdUp{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}\n\n@media(max-width:600px){\n  .date-row{grid-template-columns:1fr}.darrow{display:none}\n  .exp-grid{grid-template-columns:1fr 1fr}.m2{grid-template-columns:1fr}\n  .tbhead{flex-direction:column;align-items:flex-start}\n}\n::-webkit-scrollbar{width:5px;height:5px}::-webkit-scrollbar-track{background:transparent}::-webkit-scrollbar-thumb{background:rgba(255,255,255,.11);border-radius:3px}\n\n/* \u2500\u2500\u2500 RECONNECT BANNER \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n#reconnectBanner{\n  display:none;position:fixed;top:0;left:0;right:0;z-index:999;\n  background:linear-gradient(135deg,#1a0a0a,#2d0f1f);\n  border-bottom:1px solid rgba(251,113,133,.4);\n  padding:0;\n}\n#reconnectBanner.show{display:block;animation:slideDown .35s ease both}\n@keyframes slideDown{from{transform:translateY(-100%);opacity:0}to{transform:none;opacity:1}}\n.rb-inner{\n  max-width:900px;margin:0 auto;padding:14px 28px;\n  display:flex;align-items:center;gap:14px;flex-wrap:wrap;\n}\n.rb-icon{font-size:1.3rem;flex-shrink:0}\n.rb-text{flex:1;min-width:200px}\n.rb-title{font-family:'DM Sans',sans-serif;font-weight:700;font-size:.88rem;color:var(--ro);margin-bottom:2px}\n.rb-sub{font-size:.75rem;color:rgba(251,113,133,.7);font-family:'DM Mono',monospace;line-height:1.5}\n.rb-actions{display:flex;gap:8px;align-items:center;flex-shrink:0}\n.btn-reconnect{\n  display:inline-flex;align-items:center;gap:7px;\n  padding:9px 18px;border-radius:9px;border:none;cursor:pointer;\n  font-family:'DM Sans',sans-serif;font-weight:700;font-size:.82rem;\n  background:linear-gradient(135deg,#e11d48,var(--ro));color:#fff;\n  box-shadow:0 4px 16px rgba(251,113,133,.4);\n  transition:all .2s;\n}\n.btn-reconnect:hover{box-shadow:0 6px 22px rgba(251,113,133,.6);transform:translateY(-1px)}\n.btn-reconnect:active{transform:scale(.97)}\n.btn-reconnect svg{flex-shrink:0}\n.rb-dismiss{\n  background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.15);\n  color:var(--muted);padding:8px 14px;border-radius:8px;\n  font-family:'DM Mono',monospace;font-size:.65rem;cursor:pointer;\n  transition:all .15s;white-space:nowrap;\n}\n.rb-dismiss:hover{background:rgba(255,255,255,.14);color:var(--text)}\n\n/* Push page content down when banner is visible */\nbody.banner-on .wrap{padding-top:20px}\nbody.banner-on .hero{padding-top:96px}\n\n/* \u2500\u2500\u2500 FULL-PAGE RECONNECT OVERLAY \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n#reconnectOverlay{\n  display:none;position:fixed;inset:0;z-index:1000;\n  background:rgba(6,4,15,.92);backdrop-filter:blur(16px);\n  align-items:center;justify-content:center;padding:24px;\n}\n#reconnectOverlay.show{display:flex;animation:fadeIn .3s ease}\n@keyframes fadeIn{from{opacity:0}to{opacity:1}}\n.ro-card{\n  background:rgba(19,16,42,.98);border:1px solid rgba(251,113,133,.35);\n  border-radius:24px;padding:42px 38px;max-width:500px;width:100%;\n  position:relative;overflow:hidden;\n  box-shadow:0 48px 120px rgba(0,0,0,.8);\n  animation:mIn .3s ease;\n  text-align:center;\n}\n.ro-card::before{\n  content:'';position:absolute;top:0;left:0;right:0;height:2px;\n  background:linear-gradient(90deg,var(--ro),var(--am),var(--vi));\n}\n.ro-icon-wrap{\n  width:72px;height:72px;border-radius:20px;\n  background:rgba(251,113,133,.1);border:1px solid rgba(251,113,133,.3);\n  display:flex;align-items:center;justify-content:center;\n  font-size:2rem;margin:0 auto 20px;\n}\n.ro-badge{\n  display:inline-flex;align-items:center;gap:6px;margin-bottom:16px;\n  font-family:'DM Mono',monospace;font-size:.6rem;letter-spacing:.14em;text-transform:uppercase;\n  color:var(--ro);background:rgba(251,113,133,.1);border:1px solid rgba(251,113,133,.25);\n  padding:5px 13px;border-radius:99px;\n}\n.ro-card h2{\n  font-family:'Playfair Display',serif;font-size:1.75rem;font-weight:900;\n  margin-bottom:10px;line-height:1.1;\n}\n.ro-card p{font-size:.875rem;color:var(--muted);line-height:1.75;margin-bottom:14px}\n.ro-steps{\n  text-align:left;background:rgba(255,255,255,.03);\n  border:1px solid var(--border2);border-radius:12px;\n  padding:16px 18px;margin:18px 0 24px;\n  display:flex;flex-direction:column;gap:10px;\n}\n.ro-step{display:flex;align-items:flex-start;gap:10px;font-size:.82rem;color:var(--muted);line-height:1.55}\n.ro-sn{\n  flex-shrink:0;min-width:22px;height:22px;\n  background:rgba(0,229,160,.14);border:1px solid rgba(0,229,160,.3);\n  border-radius:6px;display:flex;align-items:center;justify-content:center;\n  font-family:'DM Mono',monospace;font-size:.6rem;color:var(--em);font-weight:700;\n}\n.ro-step strong{color:var(--text)}\n.ro-card-actions{display:flex;flex-direction:column;gap:10px}\n.btn-reconnect-lg{\n  display:flex;align-items:center;justify-content:center;gap:9px;\n  width:100%;padding:15px;border-radius:12px;border:none;cursor:pointer;\n  font-family:'DM Sans',sans-serif;font-weight:700;font-size:.94rem;\n  background:linear-gradient(135deg,#e11d48,var(--ro));color:#fff;\n  box-shadow:0 6px 28px rgba(251,113,133,.4);transition:all .2s;\n}\n.btn-reconnect-lg:hover{box-shadow:0 8px 36px rgba(251,113,133,.65);transform:translateY(-2px)}\n.btn-reconnect-lg:active{transform:scale(.97)}\n.ro-later{\n  font-family:'DM Mono',monospace;font-size:.65rem;color:var(--faint);\n  cursor:pointer;padding:6px;transition:color .15s;background:none;border:none;\n  text-decoration:underline;\n}\n.ro-later:hover{color:var(--muted)}\n\n\n/* \u2500\u2500\u2500 STICKY TOP NAV \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.topnav{\n  position:fixed;top:0;left:0;right:0;z-index:500;\n  background:rgba(6,4,15,.82);backdrop-filter:blur(20px);\n  border-bottom:1px solid var(--border);\n  padding:0;\n  transition:transform .3s ease;\n}\n.topnav-inner{\n  max-width:900px;margin:0 auto;padding:0 28px;\n  height:54px;display:flex;align-items:center;justify-content:space-between;gap:12px;\n}\n.topnav-brand{\n  font-family:'Playfair Display',serif;font-weight:900;font-size:1.08rem;\n  color:var(--text);text-decoration:none;flex-shrink:0;\n}\n.topnav-brand span{color:var(--em)}\n.topnav-actions{display:flex;align-items:center;gap:8px;flex-shrink:0}\n.nav-pill{\n  display:inline-flex;align-items:center;gap:6px;\n  padding:7px 14px;border-radius:8px;border:1px solid var(--border2);\n  background:rgba(255,255,255,.05);color:var(--muted);\n  font-family:'DM Sans',sans-serif;font-weight:600;font-size:.78rem;\n  cursor:pointer;transition:all .2s;white-space:nowrap;\n}\n.nav-pill:hover{background:rgba(255,255,255,.1);color:var(--text);border-color:rgba(255,255,255,.25)}\n.nav-pill svg{flex-shrink:0}\n.nav-pill-help:hover{background:rgba(167,139,250,.12);color:var(--vi);border-color:rgba(167,139,250,.3)}\n.nav-pill-logout{color:var(--ro)}\n.nav-pill-logout:hover{background:rgba(251,113,133,.12);color:var(--ro);border-color:rgba(251,113,133,.3)}\n/* push hero down so it doesn't hide under nav */\nbody{padding-top:54px}\nbody.banner-on .hero{padding-top:106px}\n\n/* \u2500\u2500\u2500 HELP MODAL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n#helpModal .modal{max-width:580px}\n.help-section{margin-bottom:22px}\n.help-section:last-child{margin-bottom:0}\n.help-h{\n  font-family:'DM Mono',monospace;font-size:.6rem;letter-spacing:.14em;\n  text-transform:uppercase;color:var(--em);margin-bottom:10px;\n  display:flex;align-items:center;gap:7px;\n}\n.help-h::after{content:'';flex:1;height:1px;background:rgba(0,229,160,.18)}\n.help-item{\n  display:flex;align-items:flex-start;gap:11px;\n  padding:10px 12px;border-radius:10px;background:rgba(255,255,255,.03);\n  border:1px solid var(--border);margin-bottom:7px;\n  font-size:.83rem;color:var(--muted);line-height:1.6;\n}\n.help-item:last-child{margin-bottom:0}\n.help-ico{font-size:1.1rem;flex-shrink:0;margin-top:1px}\n.help-item strong{color:var(--text);display:block;margin-bottom:2px;font-size:.82rem}\n.help-tip{\n  background:rgba(96,165,250,.07);border:1px solid rgba(96,165,250,.2);\n  border-radius:9px;padding:11px 14px;font-size:.78rem;color:var(--bl);\n  line-height:1.65;display:flex;gap:9px;align-items:flex-start;\n}\n.help-tip-ico{flex-shrink:0;margin-top:1px}\n\n/* \u2500\u2500\u2500 LOGOUT CONFIRM MODAL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n#logoutModal .modal{max-width:420px}\n.logout-body{text-align:center;padding:10px 0 4px}\n.logout-icon{font-size:2.8rem;margin-bottom:14px;display:block}\n.logout-title{font-family:'Playfair Display',serif;font-size:1.3rem;font-weight:700;margin-bottom:8px}\n.logout-sub{font-size:.85rem;color:var(--muted);line-height:1.7;margin-bottom:0}\n.logout-sub strong{color:var(--text)}\n\n/* \u2500\u2500\u2500 UNLINK MODAL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n#unlinkModal .modal{max-width:500px}\n.nav-pill-unlink{color:var(--am)}\n.nav-pill-unlink:hover{background:rgba(251,191,36,.12);color:var(--am);border-color:rgba(251,191,36,.3)}\n.unlink-scroll-box{\n  max-height:260px;overflow-y:auto;\n  border:1px solid var(--border2);border-radius:12px;\n  padding:18px 20px;background:rgba(255,255,255,.03);\n  font-size:.84rem;color:var(--muted);line-height:1.75;\n  scroll-behavior:smooth;\n}\n.unlink-scroll-box::-webkit-scrollbar{width:4px}\n.unlink-scroll-box::-webkit-scrollbar-thumb{background:rgba(255,255,255,.14);border-radius:3px}\n.unlink-read-notice{\n  display:flex;align-items:center;gap:8px;\n  font-family:'DM Mono',monospace;font-size:.62rem;color:var(--am);\n  margin-top:10px;letter-spacing:.05em;transition:opacity .3s;\n}\n.unlink-read-notice svg{flex-shrink:0}\n.unlink-scroll-box h4{\n  font-family:'Playfair Display',serif;font-size:1rem;\n  color:var(--text);margin-bottom:12px;\n}\n.unlink-step{\n  display:flex;align-items:flex-start;gap:10px;\n  padding:10px 0;border-bottom:1px solid var(--border);\n}\n.unlink-step:last-child{border-bottom:none;padding-bottom:0}\n.unlink-sn{\n  flex-shrink:0;width:22px;height:22px;\n  background:rgba(251,191,36,.14);border:1px solid rgba(251,191,36,.3);\n  border-radius:6px;display:flex;align-items:center;justify-content:center;\n  font-family:'DM Mono',monospace;font-size:.6rem;color:var(--am);font-weight:700;\n}\n.unlink-step p{margin:0;font-size:.83rem}\n.unlink-step strong{color:var(--text)}\n.unlink-warning{\n  display:flex;gap:10px;align-items:flex-start;\n  background:rgba(251,113,133,.08);border:1px solid rgba(251,113,133,.25);\n  border-radius:9px;padding:12px 14px;\n  font-size:.8rem;color:var(--ro);line-height:1.65;margin-top:14px;\n}\n.btn-unlink-redirect{\n  background:linear-gradient(135deg,#d97706,var(--am));\n  color:#06040f;font-weight:700;\n  box-shadow:0 4px 18px rgba(251,191,36,.3);\n}\n.btn-unlink-redirect:hover:not(:disabled){box-shadow:0 6px 26px rgba(251,191,36,.55);transform:translateY(-1px)}\n.btn-unlink-redirect:disabled{opacity:.32;cursor:not-allowed;pointer-events:none}\n\n</style>\n</head>\n<body>\n\n<!-- \u2500\u2500\u2500 STICKY TOP NAV \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n<nav class=\"topnav\">\n  <div class=\"topnav-inner\">\n    <a class=\"topnav-brand\" href=\"#\">Mail<span>Vault</span></a>\n    <div class=\"topnav-actions\">\n      <button class=\"nav-pill nav-pill-help\" onclick=\"openHelp()\">\n        <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.09 9a3 3 0 015.83 1c0 2-3 3-3 3\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\n        Help\n      </button>\n      <button class=\"nav-pill nav-pill-logout\" id=\"logoutNavBtn\" onclick=\"openLogout()\" style=\"display:none\">\n        <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M9 21H5a2 2 0 01-2-2V5a2 2 0 012-2h4\"/><polyline points=\"16 17 21 12 16 7\"/><line x1=\"21\" y1=\"12\" x2=\"9\" y2=\"12\"/></svg>\n        Sign Out\n      </button>\n      <button class=\"nav-pill nav-pill-unlink\" id=\"unlinkNavBtn\" onclick=\"openUnlink()\" style=\"display:none\">\n        <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M10 13a5 5 0 007.54.54l3-3a5 5 0 00-7.07-7.07l-1.72 1.71\"/><path d=\"M14 11a5 5 0 00-7.54-.54l-3 3a5 5 0 007.07 7.07l1.71-1.71\"/><line x1=\"2\" y1=\"2\" x2=\"22\" y2=\"22\" stroke-width=\"2\"/></svg>\n        Unlink\n      </button>\n    </div>\n  </div>\n</nav>\n\n<!-- \u2500\u2500\u2500 RECONNECT BANNER (shown when permissions are revoked) \u2500\u2500\u2500 -->\n<div id=\"reconnectBanner\">\n  <div class=\"rb-inner\">\n    <div class=\"rb-icon\">\ud83d\udd0c</div>\n    <div class=\"rb-text\">\n      <div class=\"rb-title\">MailVault is disconnected</div>\n      <div class=\"rb-sub\" id=\"rbEmail\">Gmail access was removed from this account \u2014 reconnect to restore full access.</div>\n    </div>\n    <div class=\"rb-actions\">\n      <button class=\"btn-reconnect\" id=\"rbReconnectBtn\" onclick=\"doReconnect()\">\n        <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M23 4v6h-6\"/><path d=\"M1 20v-6h6\"/><path d=\"M3.51 9a9 9 0 0114.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0020.49 15\"/></svg>\n        Reconnect Now\n      </button>\n      <button class=\"rb-dismiss\" onclick=\"dismissBanner()\">Dismiss</button>\n    </div>\n  </div>\n</div>\n\n<!-- \u2500\u2500\u2500 RECONNECT FULL-PAGE OVERLAY \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n<div id=\"reconnectOverlay\">\n  <div class=\"ro-card\">\n    <div class=\"ro-icon-wrap\">\ud83d\udd0c</div>\n    <div class=\"ro-badge\">Connection Lost</div>\n    <h2>Reconnect to<br>Mail<span class=\"grd\">Vault</span></h2>\n    <p>MailVault lost access to your Gmail because permissions were removed from your Google account. This usually happens after visiting <strong style=\"color:var(--text)\">myaccount.google.com/permissions</strong> and removing the app.</p>\n    <div class=\"ro-steps\">\n      <div class=\"ro-step\"><div class=\"ro-sn\">1</div><span>Click <strong>Reconnect</strong> below \u2014 you will be taken back to the app URL.</span></div>\n      <div class=\"ro-step\"><div class=\"ro-sn\">2</div><span>Google will show the <strong>authorization dialog</strong> again automatically.</span></div>\n      <div class=\"ro-step\"><div class=\"ro-sn\">3</div><span>Click <strong>Allow</strong> to restore Gmail access \u2014 then use the app normally.</span></div>\n    </div>\n    <div class=\"ro-card-actions\">\n      <button class=\"btn-reconnect-lg\" id=\"overlayReconnectBtn\" onclick=\"doReconnect()\">\n        <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M23 4v6h-6\"/><path d=\"M1 20v-6h6\"/><path d=\"M3.51 9a9 9 0 0114.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0020.49 15\"/></svg>\n        Reconnect to MailVault\n      </button>\n      <button class=\"ro-later\" onclick=\"dismissOverlay()\">Continue without reconnecting</button>\n    </div>\n  </div>\n</div>\n\n<div class=\"bg-orbs\"><div class=\"orb orb1\"></div><div class=\"orb orb2\"></div><div class=\"orb orb3\"></div></div>\n<div class=\"wrap\">\n\n<!-- HERO -->\n<div class=\"hero\">\n  <div class=\"hero-pill\">Gmail Exporter \u00b7 Google Apps Script</div>\n  <h1>Mail<span class=\"grd\">Vault</span></h1>\n  <p class=\"hero-sub\">Export your Gmail to CSV, PDF, or Text. Runs entirely inside your Google account \u2014 nothing leaves Google's servers.</p>\n  <div id=\"userPill\" class=\"user-badge\"><span class=\"live-dot\"></span><span id=\"userEmailDisplay\">loading\u2026</span></div>\n</div>\n\n<!-- STEP 1 -->\n<div class=\"glass\">\n  <div class=\"stripe s-em\"></div>\n  <div class=\"chead\"><span class=\"chip c-em\">Step 01</span><span class=\"ctitle\">Select Date Range</span></div>\n  <div class=\"field\">\n    <div class=\"date-row\">\n      <div><label class=\"flbl\">From</label><input type=\"date\" id=\"dateFrom\"></div>\n      <div class=\"darrow\">\u2192</div>\n      <div><label class=\"flbl\">To</label><input type=\"date\" id=\"dateTo\"></div>\n    </div>\n    <p class=\"hint\">\ud83d\udca1 Same date in both fields exports a single day</p>\n  </div>\n</div>\n\n<!-- STEP 2 -->\n<div class=\"glass\">\n  <div class=\"stripe s-vi\"></div>\n  <div class=\"chead\"><span class=\"chip c-vi\">Step 02</span><span class=\"ctitle\">Fetch Emails</span></div>\n  <p style=\"color:var(--muted);font-size:.875rem;line-height:1.7;margin-bottom:22px\">Search your Gmail for the selected date range. Review, edit, or remove emails before exporting.</p>\n  <div class=\"brow\">\n    <button class=\"btn btn-em\" id=\"fetchBtn\" onclick=\"fetchEmails()\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z\"/></svg>\n      Fetch Emails\n    </button>\n    <button class=\"btn btn-ghost\" id=\"clearBtn\" onclick=\"clearAll()\" style=\"display:none\">\u2715 Clear</button>\n  </div>\n  <div class=\"status\" id=\"fetchStatus\"><span class=\"sico\" id=\"fetchIcon\"></span><span id=\"fetchText\"></span></div>\n  <div class=\"prog-wrap\" id=\"fetchProg\">\n    <div class=\"prog-top\"><span id=\"progLabel\">Searching Gmail\u2026</span><span id=\"progPct\">\u2014</span></div>\n    <div class=\"prog-track\"><div class=\"prog-fill\" id=\"progFill\"></div></div>\n  </div>\n</div>\n\n<!-- EMAIL TABLE -->\n<div class=\"es-wrap\" id=\"emailSection\">\n  <div class=\"glass\">\n    <div class=\"stripe s-vi\"></div>\n    <div class=\"tbhead\">\n      <div style=\"display:flex;align-items:center;gap:14px;flex-wrap:wrap\">\n        <div class=\"tblbl\"><div class=\"eyebrow\">Results</div><div class=\"tbtitle\">Manage Emails</div></div>\n        <span class=\"cnt-badge\">\n          <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z\"/><polyline points=\"22,6 12,13 2,6\"/></svg>\n          <span id=\"emailCount\">0</span> emails\n        </span>\n      </div>\n      <div class=\"sort-row\">\n        <span class=\"slbl\">Sort</span>\n        <button class=\"sb on\" id=\"sortNewest\" onclick=\"sortEmails('newest')\">Newest</button>\n        <button class=\"sb\" id=\"sortOldest\" onclick=\"sortEmails('oldest')\">Oldest</button>\n        <button class=\"sb\" id=\"sortSubject\" onclick=\"sortEmails('subject')\">Subject</button>\n        <button class=\"sb\" id=\"sortFrom\" onclick=\"sortEmails('from')\">From</button>\n      </div>\n    </div>\n    <div class=\"twrap\">\n      <table>\n        <thead><tr><th class=\"td-n\">#</th><th>Subject</th><th>From</th><th>Date</th><th>Labels</th><th>Actions</th></tr></thead>\n        <tbody id=\"emailTbody\"></tbody>\n      </table>\n    </div>\n    <p style=\"font-size:.62rem;color:var(--faint);margin-top:9px;font-family:'DM Mono',monospace;line-height:1.5\">\n      <span id=\"showNote\"></span> \u00b7 Edits only affect the export \u2014 your Gmail is unchanged.\n    </p>\n  </div>\n</div>\n\n<!-- STEP 3 -->\n<div class=\"glass\" id=\"exportCard\" style=\"display:none\">\n  <div class=\"stripe s-ro\"></div>\n  <div class=\"chead\"><span class=\"chip c-ro\">Step 03</span><span class=\"ctitle\">Export to Your Device</span></div>\n  <p style=\"color:var(--muted);font-size:.875rem;line-height:1.7;margin-bottom:22px\">Files download straight to your device \u2014 nothing is sent to Google Drive or any server.</p>\n  <div class=\"exp-grid\">\n    <div class=\"ec ec-csv sel\" id=\"opt-csv\" onclick=\"selectExport('csv')\">\n      <div class=\"ck\">\u2713</div><span class=\"eico\">\ud83d\udcca</span>\n      <div class=\"ename\">CSV / Excel</div><div class=\"edesc\">Opens in Excel or Sheets</div>\n    </div>\n    <div class=\"ec ec-pdf\" id=\"opt-pdf\" onclick=\"selectExport('pdf')\">\n      <div class=\"ck\">\u2713</div><span class=\"eico\">\ud83d\udcd5</span>\n      <div class=\"ename\">PDF</div><div class=\"edesc\">Print-ready, save via browser</div>\n    </div>\n    <div class=\"ec ec-txt\" id=\"opt-txt\" onclick=\"selectExport('txt')\">\n      <div class=\"ck\">\u2713</div><span class=\"eico\">\ud83d\udcc4</span>\n      <div class=\"ename\">Text File</div><div class=\"edesc\">Plain .txt, one email per block</div>\n    </div>\n  </div>\n  <div class=\"brow\">\n    <button class=\"btn btn-em\" id=\"exportBtn\" onclick=\"runExport()\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n      <span id=\"expBtnLbl\">Download as CSV</span>\n    </button>\n  </div>\n  <div class=\"status\" id=\"exportStatus\"><span class=\"sico\" id=\"exportIcon\"></span><span id=\"exportText\"></span></div>\n</div>\n\n<footer class=\"sfooter\">\n  <div class=\"fbrand\">Mail<span>Vault</span></div>\n  <div class=\"fmeta\">Runs inside your Google Account \u00b7 No external servers<br>Files saved directly to your device</div>\n</footer>\n</div>\n\n\n<!-- \u2500\u2500\u2500 HELP MODAL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n<div class=\"mov\" id=\"helpModal\" onclick=\"closeHelpBg(event)\">\n  <div class=\"modal\">\n    <div class=\"mhd\">\n      <div class=\"mhd-t\">\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--vi)\" stroke-width=\"2.5\" style=\"margin-right:8px;vertical-align:-2px\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.09 9a3 3 0 015.83 1c0 2-3 3-3 3\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\n        Help &amp; Guide\n      </div>\n      <button class=\"mx\" onclick=\"closeHelp()\">\u2715</button>\n    </div>\n    <div class=\"mbd\">\n\n      <div class=\"help-section\">\n        <div class=\"help-h\">Getting Started</div>\n        <div class=\"help-item\"><div class=\"help-ico\">\ud83d\udcc5</div><div><strong>Step 1 \u2014 Select Date Range</strong>Pick a From and To date. Use the same date in both fields to export a single day.</div></div>\n        <div class=\"help-item\"><div class=\"help-ico\">\ud83d\udcec</div><div><strong>Step 2 \u2014 Fetch Emails</strong>Click Fetch Emails to search your Gmail. Large inboxes may take a moment \u2014 the progress bar shows status.</div></div>\n        <div class=\"help-item\"><div class=\"help-ico\">\u270f\ufe0f</div><div><strong>Review &amp; Edit</strong>Use the table to view, edit, or remove emails before exporting. Changes only affect the export \u2014 your Gmail is untouched.</div></div>\n        <div class=\"help-item\"><div class=\"help-ico\">\ud83d\udcbe</div><div><strong>Step 3 \u2014 Export</strong>Choose CSV, PDF, or Text and click Download. The file saves directly to your device \u2014 nothing goes to Google Drive.</div></div>\n      </div>\n\n      <div class=\"help-section\">\n        <div class=\"help-h\">Export Formats</div>\n        <div class=\"help-item\"><div class=\"help-ico\">\ud83d\udcca</div><div><strong>CSV / Excel</strong>Best for analysis. Opens in Excel, Google Sheets, or any spreadsheet app. Includes all fields and a summary sheet.</div></div>\n        <div class=\"help-item\"><div class=\"help-ico\">\ud83d\udcd5</div><div><strong>PDF</strong>Opens a print dialog \u2014 choose \"Save as PDF\" to download. Best for archiving or sharing.</div></div>\n        <div class=\"help-item\"><div class=\"help-ico\">\ud83d\udcc4</div><div><strong>Text File</strong>Plain .txt with one email per block. Best for reading in a text editor or scripting.</div></div>\n      </div>\n\n      <div class=\"help-section\">\n        <div class=\"help-h\">Privacy &amp; Security</div>\n        <div class=\"help-item\"><div class=\"help-ico\">\ud83d\udd12</div><div><strong>Runs inside your Google Account</strong>MailVault is a Google Apps Script. It never contacts external servers \u2014 all processing happens inside Google's own infrastructure.</div></div>\n        <div class=\"help-item\"><div class=\"help-ico\">\ud83d\udc41</div><div><strong>Read-only Gmail access</strong>MailVault only reads emails. It cannot send, delete, or modify anything in your Gmail.</div></div>\n      </div>\n\n      <div class=\"help-section\">\n        <div class=\"help-h\">Troubleshooting</div>\n        <div class=\"help-item\"><div class=\"help-ico\">\u26a0\ufe0f</div><div><strong>\"Gmail access was revoked\"</strong>You may have removed MailVault from your Google account permissions. Use the Reconnect button that appears, or reload the page.</div></div>\n        <div class=\"help-item\"><div class=\"help-ico\">\ud83d\udd0d</div><div><strong>No emails found</strong>Check your date range. Gmail search uses UTC dates, so emails near midnight may appear on a different day.</div></div>\n        <div class=\"help-item\"><div class=\"help-ico\">\ud83d\udc22</div><div><strong>Fetch is slow</strong>Large date ranges with thousands of emails take longer. Try narrowing the range to a week at a time.</div></div>\n        <div class=\"help-tip\">\n          <div class=\"help-tip-ico\">\ud83d\udca1</div>\n          <div>MailVault processes emails in batches of 500. For very large mailboxes, split into multiple smaller exports by date range.</div>\n        </div>\n      </div>\n\n    </div>\n    <div class=\"mft\">\n      <button class=\"btn btn-ghost\" onclick=\"closeHelp()\">Close</button>\n    </div>\n  </div>\n</div>\n\n<!-- \u2500\u2500\u2500 LOGOUT CONFIRM MODAL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n<div class=\"mov\" id=\"logoutModal\" onclick=\"closeLogoutBg(event)\">\n  <div class=\"modal\">\n    <div class=\"mhd\">\n      <div class=\"mhd-t\">Sign Out</div>\n      <button class=\"mx\" onclick=\"closeLogout()\">\u2715</button>\n    </div>\n    <div class=\"mbd\">\n      <div class=\"logout-body\">\n        <span class=\"logout-icon\">\ud83d\udc4b</span>\n        <div class=\"logout-title\">Sign out of MailVault?</div>\n        <p class=\"logout-sub\">You'll be signed out of your Google account in this browser. You're currently signed in as <strong id=\"logoutEmailDisplay\">\u2014</strong>.</p>\n      </div>\n    </div>\n    <div class=\"mft\">\n      <button class=\"btn btn-ghost\" onclick=\"closeLogout()\">Cancel</button>\n      <button class=\"btn btn-ro\" id=\"confirmLogoutBtn\" onclick=\"doLogout()\">\n        <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M9 21H5a2 2 0 01-2-2V5a2 2 0 012-2h4\"/><polyline points=\"16 17 21 12 16 7\"/><line x1=\"21\" y1=\"12\" x2=\"9\" y2=\"12\"/></svg>\n        Sign Out\n      </button>\n    </div>\n  </div>\n</div>\n\n<!-- \u2500\u2500\u2500 UNLINK MODAL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n<div class=\"mov\" id=\"unlinkModal\" onclick=\"closeUnlinkBg(event)\">\n  <div class=\"modal\">\n    <div class=\"mhd\">\n      <div class=\"mhd-t\">\n        <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--am)\" stroke-width=\"2.5\" style=\"margin-right:7px;vertical-align:-2px\"><path d=\"M10 13a5 5 0 007.54.54l3-3a5 5 0 00-7.07-7.07l-1.72 1.71\"/><path d=\"M14 11a5 5 0 00-7.54-.54l-3 3a5 5 0 007.07 7.07l1.71-1.71\"/><line x1=\"2\" y1=\"2\" x2=\"22\" y2=\"22\" stroke-width=\"2\"/></svg>\n        Unlink MailVault\n      </div>\n      <button class=\"mx\" onclick=\"closeUnlink()\">\u2715</button>\n    </div>\n    <div class=\"mbd\">\n      <div id=\"unlinkScrollBox\" class=\"unlink-scroll-box\" onscroll=\"onUnlinkScroll()\">\n        <h4>\u26a0\ufe0f Before you unlink \u2014 please read carefully</h4>\n\n        <div class=\"unlink-step\">\n          <div class=\"unlink-sn\">1</div>\n          <p>Clicking <strong>Go to Google Permissions</strong> will open <strong>myaccount.google.com/permissions</strong> in this same tab. You will leave MailVault.</p>\n        </div>\n        <div class=\"unlink-step\">\n          <div class=\"unlink-sn\">2</div>\n          <p>On that page, find <strong>MailVault</strong> (or your Apps Script app name) in the list of apps that have access to your Google account.</p>\n        </div>\n        <div class=\"unlink-step\">\n          <div class=\"unlink-sn\">3</div>\n          <p>Click the app name, then click <strong>\"Remove Access\"</strong> to revoke Gmail permissions for MailVault.</p>\n        </div>\n        <div class=\"unlink-step\">\n          <div class=\"unlink-sn\">4</div>\n          <p>After removing access, MailVault will no longer be able to read your Gmail. To use it again, you will need to <strong>reconnect and re-authorize</strong> the app.</p>\n        </div>\n        <div class=\"unlink-step\">\n          <div class=\"unlink-sn\">5</div>\n          <p><strong>Your Gmail is not affected.</strong> Unlinking only removes MailVault's read access \u2014 no emails are deleted or modified.</p>\n        </div>\n\n        <div class=\"unlink-warning\">\n          <span style=\"font-size:1.1rem;flex-shrink:0\">\ud83d\udd34</span>\n          <span>This action is <strong>irreversible</strong> until you re-authorize. Any in-progress exports will stop working immediately after unlinking.</span>\n        </div>\n      </div>\n\n      <div class=\"unlink-read-notice\" id=\"unlinkReadNotice\">\n        <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><polyline points=\"18 15 12 9 6 15\"/></svg>\n        Scroll down to read all instructions to continue\n      </div>\n    </div>\n    <div class=\"mft\">\n      <button class=\"btn btn-ghost\" onclick=\"closeUnlink()\">Cancel</button>\n      <button class=\"btn btn-unlink-redirect\" id=\"unlinkRedirectBtn\" onclick=\"doUnlinkRedirect()\" disabled>\n        <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M10 13a5 5 0 007.54.54l3-3a5 5 0 00-7.07-7.07l-1.72 1.71\"/><path d=\"M14 11a5 5 0 00-7.54-.54l-3 3a5 5 0 007.07 7.07l1.71-1.71\"/><line x1=\"2\" y1=\"2\" x2=\"22\" y2=\"22\" stroke-width=\"2\"/></svg>\n        Go to Google Permissions\n      </button>\n    </div>\n  </div>\n</div>\n\n<!-- MODAL -->\n<div class=\"mov\" id=\"modal\" onclick=\"closeMBg(event)\">\n  <div class=\"modal\">\n    <div class=\"mhd\"><div class=\"mhd-t\" id=\"modalTitle\">Email</div><button class=\"mx\" onclick=\"closeM()\">\u2715</button></div>\n    <div class=\"mbd\" id=\"modalBody\"></div>\n    <div class=\"mft\" id=\"modalFoot\"></div>\n  </div>\n</div>\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nlet emails=[],currentSort='newest',selExp='csv',editIdx=null;\n\n// \u2500\u2500 page init \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nvar _reconnectUrl = '';\n\n(function(){\n  const t=new Date().toISOString().split('T')[0];\n  document.getElementById('dateFrom').value=t;\n  document.getElementById('dateTo').value=t;\n\n  // Check permissions on load \u2014 catches revoked access immediately\n  google.script.run\n    .withSuccessHandler(function(r){\n      if (!r) return;\n\n      // Always update the user pill with the email\n      if (r.email) {\n        document.getElementById('userEmailDisplay').textContent = r.email;\n        document.getElementById('userPill').style.display = 'inline-flex';\n        // Show logout button + populate logout modal email\n        document.getElementById('logoutNavBtn').style.display = 'inline-flex';\n        document.getElementById('unlinkNavBtn').style.display = 'inline-flex';\n        document.getElementById('logoutEmailDisplay').textContent = r.email;\n      }\n\n      if (r.status === 'revoked') {\n        // Store reconnect URL for buttons\n        _reconnectUrl = r.reconnectUrl || '';\n\n        // Update banner email line\n        if (r.email) {\n          document.getElementById('rbEmail').textContent =\n            r.email + ' \u2014 Gmail access was removed. Reconnect to restore it.';\n        }\n\n        // Decide: show overlay (first load, nothing done yet) or just banner\n        showReconnectBanner();\n\n      } else {\n        // All good \u2014 hide any leftover banner\n        hideReconnectBanner();\n      }\n    })\n    .withFailureHandler(function(){\n      // checkPermissions failed (script error) \u2014 fall back to getUserEmail silently\n      google.script.run\n        .withSuccessHandler(function(r){\n          if(r&&r.email){\n            document.getElementById('userEmailDisplay').textContent=r.email;\n            document.getElementById('userPill').style.display='inline-flex';\n          }\n        })\n        .withFailureHandler(function(){})\n        .getUserEmail();\n    })\n    .checkPermissions();\n})();\n\n// \u2500\u2500 reconnect banner helpers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction showReconnectBanner() {\n  document.getElementById('reconnectBanner').classList.add('show');\n  document.body.classList.add('banner-on');\n}\nfunction hideReconnectBanner() {\n  document.getElementById('reconnectBanner').classList.remove('show');\n  document.getElementById('reconnectOverlay').classList.remove('show');\n  document.body.classList.remove('banner-on');\n}\nfunction showReconnectOverlay() {\n  document.getElementById('reconnectOverlay').classList.add('show');\n}\nfunction dismissBanner() {\n  document.getElementById('reconnectBanner').classList.remove('show');\n  document.body.classList.remove('banner-on');\n  toast('Reconnect any time using the banner at the top.', 'nn');\n}\nfunction dismissOverlay() {\n  document.getElementById('reconnectOverlay').classList.remove('show');\n}\nfunction doReconnect() {\n  if (!_reconnectUrl) {\n    // Fallback: reload the page \u2014 Apps Script will re-prompt auth\n    window.top.location.reload();\n    return;\n  }\n  // Show spinner on both buttons while navigating\n  ['rbReconnectBtn','overlayReconnectBtn'].forEach(function(id){\n    var b = document.getElementById(id);\n    if (b) { b.innerHTML = '<div class=\"spin\"></div> Reconnecting\u2026'; b.disabled = true; }\n  });\n  window.top.location.href = _reconnectUrl;\n}\n\nfunction setSt(bar,txt,ico,msg,type){\n  const m={info:'\u2139\ufe0f',success:'\u2705',error:'\u274c',warning:'\u26a0\ufe0f'};\n  document.getElementById(bar).className='status show '+type;\n  document.getElementById(txt).innerHTML=msg;\n  document.getElementById(ico).textContent=m[type]||'\u2139\ufe0f';\n}\nfunction clrSt(bar){document.getElementById(bar).className='status';}\nfunction showPr(lbl){document.getElementById('fetchProg').classList.add('show');document.getElementById('progLabel').textContent=lbl||'Working\u2026';document.getElementById('progFill').style.width='15%';document.getElementById('progPct').textContent='\u2014';}\nfunction setPr(p){document.getElementById('progFill').style.width=p+'%';document.getElementById('progPct').textContent=Math.round(p)+'%';}\nfunction hidePr(){document.getElementById('fetchProg').classList.remove('show');}\nfunction busy(id,on,lbl){const b=document.getElementById(id);if(on){b._h=b.innerHTML;b.disabled=true;b.innerHTML='<div class=\"spin\"></div> '+(lbl||'Working\u2026');}else{b.disabled=false;if(b._h)b.innerHTML=b._h;}}\nfunction toast(msg,type){const t=document.getElementById('toast');t.textContent=msg;t.className='toast show '+(type||'nn');clearTimeout(t._t);t._t=setTimeout(()=>{t.className='toast';},2800);}\nfunction esc(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');}\nfunction hesc(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');}\n\nfunction fetchEmails(){\n  const df=document.getElementById('dateFrom').value,dt=document.getElementById('dateTo').value;\n  if(!df||!dt){setSt('fetchStatus','fetchText','fetchIcon','Please select both dates.','warning');return;}\n  if(new Date(df)>new Date(dt)){setSt('fetchStatus','fetchText','fetchIcon','From date must be before To date.','warning');return;}\n  clrSt('fetchStatus');\n  document.getElementById('emailSection').classList.remove('show');\n  document.getElementById('exportCard').style.display='none';\n  document.getElementById('clearBtn').style.display='none';\n  emails=[];busy('fetchBtn',true,'Fetching\u2026');showPr('Searching your Gmail\u2026');\n  google.script.run\n    .withSuccessHandler(res=>{\n      busy('fetchBtn',false);\n      if(res.error){\n        hidePr();\n        // Detect mid-session permissions revocation\n        if(res.errorType==='permissions_revoked'){\n          setSt('fetchStatus','fetchText','fetchIcon','Gmail access was revoked. Please reconnect MailVault to continue.','error');\n          showReconnectBanner();\n          showReconnectOverlay();\n          return;\n        }\n        setSt('fetchStatus','fetchText','fetchIcon','Error: '+res.error,'error');\n        return;\n      }\n      emails=res.emails||[];setPr(100);\n      setTimeout(()=>{\n        hidePr();\n        if(!emails.length){setSt('fetchStatus','fetchText','fetchIcon','No emails found for this date range.','warning');return;}\n        sortEmails(currentSort,true);\n        setSt('fetchStatus','fetchText','fetchIcon','Found <strong>'+emails.length+'</strong> email'+(emails.length!==1?'s':'')+'. Review below before exporting.','success');\n        document.getElementById('emailSection').classList.add('show');\n        document.getElementById('exportCard').style.display='';\n        document.getElementById('clearBtn').style.display='';\n        document.getElementById('emailSection').scrollIntoView({behavior:'smooth',block:'start'});\n      },300);\n    })\n    .withFailureHandler(err=>{busy('fetchBtn',false);hidePr();setSt('fetchStatus','fetchText','fetchIcon','Script error: '+err.message,'error');})\n    .fetchEmailsByDateRange(df,dt);\n}\n\nfunction sortEmails(mode,silent){\n  currentSort=mode;\n  ['newest','oldest','subject','from'].forEach(m=>document.getElementById('sort'+m[0].toUpperCase()+m.slice(1)).classList.toggle('on',m===mode));\n  emails.sort((a,b)=>mode==='newest'?b.dateTs-a.dateTs:mode==='oldest'?a.dateTs-b.dateTs:mode==='subject'?(a.subject||'').localeCompare(b.subject||''):(a.from||'').localeCompare(b.from||''));\n  renderTable();if(!silent)toast('Sorted: '+mode,'nn');\n}\n\nfunction renderTable(){\n  const tb=document.getElementById('emailTbody');\n  document.getElementById('emailCount').textContent=emails.length;\n  document.getElementById('showNote').textContent=emails.length+' email'+(emails.length!==1?'s':'')+' in list';\n  if(!emails.length){tb.innerHTML='<tr><td colspan=\"6\" style=\"text-align:center;padding:30px;color:var(--faint);font-family:\\'DM Mono\\',monospace;font-size:.7rem\">All emails removed</td></tr>';return;}\n  tb.innerHTML=emails.map((e,i)=>{\n    const ud=!e.isRead?'<span class=\"ud\"></span>':'',ds=(e.date||'').split(' ')[0],fr=(e.from||'').replace(/<[^>]+>/g,'').trim()||e.from||'\u2014';\n    return `<tr><td class=\"td-n\">${i+1}</td><td class=\"td-s\">${ud}${esc(e.subject)}</td><td class=\"td-f\" title=\"${esc(e.from)}\">${esc(fr)}</td><td class=\"td-d\">${ds}</td><td style=\"font-size:.6rem;color:var(--faint);max-width:85px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap\">${esc(e.labels||'\u2014')}</td><td><button class=\"ra\" onclick=\"viewEmail(${i})\" title=\"View\">\ud83d\udc41</button><button class=\"ra\" onclick=\"editEmail(${i})\" title=\"Edit\">\u270f\ufe0f</button><button class=\"ra del\" onclick=\"removeEmail(${i})\" title=\"Remove\">\ud83d\uddd1</button></td></tr>`;\n  }).join('');\n}\n\nfunction viewEmail(i){\n  const e=emails[i];document.getElementById('modalTitle').textContent='Email #'+(i+1);\n  document.getElementById('modalBody').innerHTML=`<div class=\"mf\"><label>Subject</label><div class=\"mv\" style=\"font-weight:600;font-size:.98rem\">${esc(e.subject)}</div></div><div class=\"m2\"><div class=\"mf\"><label>From</label><div class=\"mv\">${esc(e.from||'\u2014')}</div></div><div class=\"mf\"><label>Date</label><div class=\"mv\">${esc(e.date||'\u2014')}</div></div><div class=\"mf\"><label>To</label><div class=\"mv\">${esc(e.to||'\u2014')}</div></div><div class=\"mf\"><label>Labels</label><div class=\"mv\">${esc(e.labels||'\u2014')}</div></div>${e.cc?`<div class=\"mf\"><label>CC</label><div class=\"mv\">${esc(e.cc)}</div></div>`:''}</div><div class=\"mf\"><label>Body Preview</label><div class=\"mbtext\">${esc(e.body||'(no body)')}</div></div><div style=\"font-size:.6rem;color:var(--faint);font-family:'DM Mono',monospace;margin-top:9px\">Read: ${e.isRead?'Yes':'No'} \u00b7 Starred: ${e.isStarred?'\u2b50 Yes':'No'} \u00b7 ${e.size} bytes</div>`;\n  document.getElementById('modalFoot').innerHTML=`<button class=\"btn btn-ghost\" onclick=\"closeM()\">Close</button><button class=\"btn btn-vi\" onclick=\"closeM();editEmail(${i})\">Edit</button>`;\n  openM();\n}\n\nfunction editEmail(i){\n  const e=emails[i];editIdx=i;document.getElementById('modalTitle').textContent='Edit Email #'+(i+1);\n  document.getElementById('modalBody').innerHTML=`<p style=\"font-size:.72rem;color:var(--faint);margin-bottom:16px;line-height:1.5;font-family:'DM Mono',monospace\">Changes only affect the export \u2014 your Gmail is untouched.</p><div class=\"mf\"><label>Subject</label><input type=\"text\" id=\"eSubj\" value=\"${esc(e.subject)}\"></div><div class=\"m2\"><div class=\"mf\"><label>From</label><input type=\"text\" id=\"eFrom\" value=\"${esc(e.from||'')}\"></div><div class=\"mf\"><label>To</label><input type=\"text\" id=\"eTo\" value=\"${esc(e.to||'')}\"></div><div class=\"mf\"><label>CC</label><input type=\"text\" id=\"eCc\" value=\"${esc(e.cc||'')}\"></div><div class=\"mf\"><label>Labels</label><input type=\"text\" id=\"eLbl\" value=\"${esc(e.labels||'')}\"></div></div><div class=\"mf\"><label>Body Preview</label><textarea id=\"eBody\" rows=\"6\" style=\"resize:vertical\">${esc(e.body||'')}</textarea></div>`;\n  document.getElementById('modalFoot').innerHTML=`<button class=\"btn btn-ghost\" onclick=\"closeM()\">Cancel</button><button class=\"btn btn-em\" onclick=\"saveEdit()\">Save Changes</button>`;\n  openM();\n}\nfunction saveEdit(){\n  if(editIdx===null)return;\n  const e=emails[editIdx];\n  e.subject=document.getElementById('eSubj').value;e.from=document.getElementById('eFrom').value;\n  e.to=document.getElementById('eTo').value;e.cc=document.getElementById('eCc').value;\n  e.labels=document.getElementById('eLbl').value;e.body=document.getElementById('eBody').value;\n  e.snippet=e.body.substring(0,200).replace(/\\n/g,' ');\n  closeM();renderTable();toast('Email #'+(editIdx+1)+' updated','ok');editIdx=null;\n}\n\nfunction removeEmail(i){const s=emails[i].subject||'(no subject)';emails.splice(i,1);renderTable();toast('Removed: '+s.substring(0,40),'nn');if(!emails.length){document.getElementById('exportCard').style.display='none';setSt('fetchStatus','fetchText','fetchIcon','All emails removed. Fetch again to start over.','warning');}}\n\nfunction openM(){document.getElementById('modal').classList.add('open');document.body.style.overflow='hidden';}\nfunction closeM(){document.getElementById('modal').classList.remove('open');document.body.style.overflow='';editIdx=null;}\nfunction closeMBg(e){if(e.target===document.getElementById('modal'))closeM();}\n\nfunction selectExport(type){\n  selExp=type;\n  document.getElementById('opt-csv').className='ec ec-csv'+(type==='csv'?' sel':'');\n  document.getElementById('opt-pdf').className='ec ec-pdf'+(type==='pdf'?' sel s-pdf':'');\n  document.getElementById('opt-txt').className='ec ec-txt'+(type==='txt'?' sel s-txt':'');\n  document.getElementById('expBtnLbl').textContent={csv:'Download as CSV',pdf:'Download as PDF',txt:'Download as Text'}[type];\n}\n\nfunction runExport(){\n  if(!emails.length){setSt('exportStatus','exportText','exportIcon','No emails to export.','warning');return;}\n  const df=document.getElementById('dateFrom').value,dt=document.getElementById('dateTo').value;\n  const ue=document.getElementById('userEmailDisplay').textContent||'unknown';\n  const fn='MailVault_'+df+(df!==dt?'_to_'+dt:'')+'_'+emails.length+'emails';\n  if(selExp==='pdf'){buildPdf(emails,ue,df,dt,fn);return;}\n  const content=selExp==='csv'?buildCsv(emails,ue,df,dt):buildTxt(emails,ue,df,dt);\n  const ext=selExp==='csv'?'.csv':'.txt',mime=selExp==='csv'?'text/csv;charset=utf-8;':'text/plain;charset=utf-8;';\n  const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');\n  a.href=url;a.download=fn+ext;a.style.display='none';document.body.appendChild(a);a.click();document.body.removeChild(a);\n  setTimeout(()=>URL.revokeObjectURL(url),2000);\n  setSt('exportStatus','exportText','exportIcon','<strong>'+emails.length+'</strong> emails saved as <strong>'+fn+ext+'</strong> \u2014 check your Downloads folder.','success');\n  toast('Downloaded '+fn+ext,'ok');\n}\n\nfunction buildCsv(emails,ue,df,dt){\n  const h=['#','Date','From','To','CC','BCC','Subject','Body Preview','Labels','Read','Starred','Size (bytes)','Message ID','Thread ID'],rows=[h];\n  emails.forEach((e,i)=>rows.push([i+1,e.date,e.from,e.to,e.cc,e.bcc,e.subject,(e.snippet||'').replace(/\\n/g,' '),e.labels,e.isRead?'Yes':'No',e.isStarred?'Yes':'No',e.size,e.id,e.threadId]));\n  rows.push([],['--- SUMMARY ---'],['Account',ue],['Date Range',df+' to '+dt],['Total',emails.length],['Exported At',new Date().toLocaleString()]);\n  return rows.map(r=>r.map(c=>{const v=String(c==null?'':c);return(v.indexOf(',')>-1||v.indexOf('\"')>-1||v.indexOf('\\n')>-1)?'\"'+v.replace(/\"/g,'\"\"')+'\"':v;}).join(',')).join('\\r\\n');\n}\n\nfunction buildPdf(emails,ue,df,dt,fn){\n  const rows=emails.map((e,i)=>`<div class=\"eb\"><div class=\"en\">#${i+1}</div><div class=\"es\">${hesc(e.subject)}</div><table class=\"mt\"><tr><td class=\"mk\">From</td><td>${hesc(e.from||'\u2014')}</td><td class=\"mk\">Date</td><td>${hesc(e.date||'\u2014')}</td></tr><tr><td class=\"mk\">To</td><td>${hesc(e.to||'\u2014')}</td><td class=\"mk\">Labels</td><td>${hesc(e.labels||'\u2014')}</td></tr>${e.cc?`<tr><td class=\"mk\">CC</td><td colspan=\"3\">${hesc(e.cc)}</td></tr>`:''}<tr><td class=\"mk\">Read</td><td>${e.isRead?'Yes':'No'}</td><td class=\"mk\">Starred</td><td>${e.isStarred?'\u2b50 Yes':'No'}</td></tr></table><div class=\"bl\">BODY PREVIEW</div><div class=\"bt\">${hesc(e.body||'(no body)')}</div></div>`).join('');\n  const html=`<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><title>${hesc(fn)}</title><style>body{font-family:Arial,sans-serif;font-size:10pt;color:#111;margin:0}.cover{padding:40pt 36pt 28pt;background:linear-gradient(135deg,#06040f,#1a0a3e);color:#fff}.cover h1{font-size:26pt;font-weight:900;margin:0 0 8pt}.cover h1 em{color:#00e5a0;font-style:normal}.cover-meta{font-size:8pt;color:rgba(255,255,255,.6);font-family:monospace;line-height:2}.eb{padding:16pt 36pt;border-bottom:1pt solid #eee;page-break-inside:avoid}.en{font-family:monospace;font-size:7pt;color:#999;margin-bottom:4pt}.es{font-size:13pt;font-weight:700;margin-bottom:10pt}.mt{width:100%;border-collapse:collapse;margin-bottom:10pt;font-size:8.5pt}.mt td{padding:3pt 6pt;border:1pt solid #e5e5e5;vertical-align:top}.mk{font-weight:700;color:#00b87c;background:#e6f9f3;width:48pt;white-space:nowrap}.bl{font-family:monospace;font-size:6.5pt;color:#aaa;letter-spacing:.12em;text-transform:uppercase;margin-bottom:5pt}.bt{font-size:8.5pt;color:#555;line-height:1.65;white-space:pre-wrap;background:#fafafa;padding:8pt;border:1pt solid #eee}@media print{@page{margin:0}.cover{padding:28pt}.eb{padding:12pt 28pt}}</style></head><body><div class=\"cover\"><h1>Mail<em>Vault</em></h1><div class=\"cover-meta\">Account: ${hesc(ue)}<br>Range: ${hesc(df)} \u2192 ${hesc(dt)}<br>Total: ${emails.length} emails<br>Exported: ${new Date().toLocaleString()}</div></div>${rows}<script>window.onload=function(){window.print();}<\\/script></body></html>`;\n  const w=window.open('','_blank','width=920,height=720');w.document.write(html);w.document.close();\n  setSt('exportStatus','exportText','exportIcon','PDF window opened \u2014 choose <strong>Save as PDF</strong> in the print dialog.','success');\n  toast('PDF ready \u2014 Print \u2192 Save as PDF','ok');\n}\n\nfunction buildTxt(emails,ue,df,dt){\n  const L=['\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550','  MAILVAULT \u2014 GMAIL EXPORT','  Account : '+ue,'  Range   : '+df+' \u2192 '+dt,'  Total   : '+emails.length+' emails','  Exported: '+new Date().toLocaleString(),'\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550',''];\n  emails.forEach((e,i)=>{L.push('\u250c\u2500 EMAIL #'+(i+1)+' '+'\u2500'.repeat(Math.max(0,48-String(i+1).length)));L.push('\u2502 Subject : '+(e.subject||'(no subject)'));L.push('\u2502 From    : '+(e.from||'\u2014'));L.push('\u2502 To      : '+(e.to||'\u2014'));if(e.cc)L.push('\u2502 CC      : '+e.cc);L.push('\u2502 Date    : '+(e.date||'\u2014'));L.push('\u2502 Labels  : '+(e.labels||'\u2014'));L.push('\u2502 Read    : '+(e.isRead?'Yes':'No')+'   Starred: '+(e.isStarred?'Yes':'No'));L.push('\u2502');L.push('\u2502 BODY:');(e.body||'(no body)').split('\\n').forEach(bl=>L.push('\u2502   '+bl));L.push('\u2514'+'\u2500'.repeat(52));L.push('');});\n  return L.join('\\n');\n}\n\n// \u2500\u2500 HELP MODAL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction openHelp(){document.getElementById('helpModal').classList.add('open');document.body.style.overflow='hidden';}\nfunction closeHelp(){document.getElementById('helpModal').classList.remove('open');document.body.style.overflow='';}\nfunction closeHelpBg(e){if(e.target===document.getElementById('helpModal'))closeHelp();}\n\n// \u2500\u2500 LOGOUT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction openLogout(){document.getElementById('logoutModal').classList.add('open');document.body.style.overflow='hidden';}\nfunction closeLogout(){document.getElementById('logoutModal').classList.remove('open');document.body.style.overflow='';}\nfunction closeLogoutBg(e){if(e.target===document.getElementById('logoutModal'))closeLogout();}\nfunction doLogout(){\n  const btn=document.getElementById('confirmLogoutBtn');\n  btn.innerHTML='<div class=\"spin\"></div> Signing out\u2026';btn.disabled=true;\n  // Get the app URL from the backend, then redirect to Google logout \u2192 back to app\n  google.script.run\n    .withSuccessHandler(function(url){\n      const appUrl=url||window.top.location.href.split('?')[0];\n      const logoutUrl='https://accounts.google.com/logout?continue='+encodeURIComponent(appUrl);\n      window.top.location.href=logoutUrl;\n    })\n    .withFailureHandler(function(){\n      // Fallback if backend call fails\n      window.top.location.href='https://accounts.google.com/logout';\n    })\n    .getAppUrl();\n}\n\n// \u2500\u2500 UNLINK \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nfunction openUnlink(){\n  // Reset scroll & button state each time modal opens\n  const box=document.getElementById('unlinkScrollBox');\n  box.scrollTop=0;\n  document.getElementById('unlinkRedirectBtn').disabled=true;\n  document.getElementById('unlinkReadNotice').style.opacity='1';\n  document.getElementById('unlinkModal').classList.add('open');\n  document.body.style.overflow='hidden';\n  // Check immediately in case content is short enough without scrolling\n  _checkUnlinkScrolled();\n}\nfunction closeUnlink(){document.getElementById('unlinkModal').classList.remove('open');document.body.style.overflow='';}\nfunction closeUnlinkBg(e){if(e.target===document.getElementById('unlinkModal'))closeUnlink();}\nfunction onUnlinkScroll(){_checkUnlinkScrolled();}\nfunction _checkUnlinkScrolled(){\n  const box=document.getElementById('unlinkScrollBox');\n  const atBottom=box.scrollHeight-box.scrollTop<=box.clientHeight+8;\n  if(atBottom){\n    document.getElementById('unlinkRedirectBtn').disabled=false;\n    document.getElementById('unlinkReadNotice').style.opacity='0';\n  }\n}\nfunction doUnlinkRedirect(){\n  window.top.location.href='https://myaccount.google.com/permissions';\n}\n\nfunction clearAll(){emails=[];currentSort='newest';document.getElementById('emailSection').classList.remove('show');document.getElementById('exportCard').style.display='none';document.getElementById('clearBtn').style.display='none';clrSt('fetchStatus');clrSt('exportStatus');hidePr();toast('Cleared','nn');}\n</script>\n</body>\n</html>"

// ── INIT: Render code into <pre> elements ─────────────────
function initCode() {
  const gsPre   = document.getElementById('gsDisplay');
  const htmlPre = document.getElementById('htmlDisplay');
  if (!gsPre || !htmlPre) return;

  gsPre.textContent   = CODE_GS;
  htmlPre.textContent = CODE_HTML;

  const gsLines   = CODE_GS.split('\n').length;
  const htmlLines = CODE_HTML.split('\n').length;
  const gsKb      = (new Blob([CODE_GS]).size   / 1024).toFixed(1);
  const htmlKb    = (new Blob([CODE_HTML]).size  / 1024).toFixed(1);

  document.getElementById('gsLineCount').textContent   = gsLines   + ' lines · ' + gsKb   + ' KB';
  document.getElementById('htmlLineCount').textContent = htmlLines + ' lines · ' + htmlKb + ' KB';
}

// ── COPY CODE ─────────────────────────────────────────────
// Handles both secure contexts (https/localhost) and
// local file:// protocol where navigator.clipboard is blocked.
function copyCode(which) {
  const code  = which === 'gs' ? CODE_GS : CODE_HTML;
  const btnId = which === 'gs' ? 'copyGsBtn' : 'copyHtmlBtn';
  const label = which === 'gs' ? 'Code.gs'   : 'index.html';
  const btn   = document.getElementById(btnId);
  const pre   = document.getElementById(which === 'gs' ? 'gsDisplay' : 'htmlDisplay');

  const svgCopy = `<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/></svg>`;
  const svgCheck = `<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>`;

  function onSuccess() {
    btn.innerHTML = svgCheck + ' Copied!';
    btn.classList.add('copied');
    showToast(label + ' copied to clipboard!');
    setTimeout(() => {
      btn.innerHTML = svgCopy + ' Copy Code';
      btn.classList.remove('copied');
    }, 2600);
  }

  function onFail() {
    // Fallback: select text so user can Ctrl+C manually
    try {
      const range = document.createRange();
      range.selectNodeContents(pre);
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
      showToast('Text selected — press Ctrl+C / Cmd+C to copy', true);
    } catch(e) {
      showToast('Could not auto-copy. Please select the code manually.', true);
    }
  }

  // Try modern Clipboard API first
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(code).then(onSuccess).catch(() => {
      // Second attempt: execCommand (works for file:// in most browsers)
      if (execCommandCopy(code)) { onSuccess(); }
      else { onFail(); }
    });
  } else {
    // No Clipboard API (file:// protocol) — use execCommand
    if (execCommandCopy(code)) { onSuccess(); }
    else { onFail(); }
  }
}

// execCommand fallback — works on local file:// in Chrome/Edge/Firefox
function execCommandCopy(text) {
  const ta = document.createElement('textarea');
  ta.value = text;
  ta.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0';
  document.body.appendChild(ta);
  ta.focus();
  ta.select();
  let ok = false;
  try { ok = document.execCommand('copy'); } catch(e) { ok = false; }
  document.body.removeChild(ta);
  return ok;
}

// ── TOAST ─────────────────────────────────────────────────
function showToast(msg, isErr) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.className = 'show' + (isErr ? ' err' : '');
  clearTimeout(t._t);
  t._t = setTimeout(() => { t.className = ''; }, 3000);
}

// ── SMOOTH SCROLL ─────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  initCode();
  document.querySelectorAll('a[href^="#"]').forEach(a => {
    a.addEventListener('click', e => {
      e.preventDefault();
      const el = document.querySelector(a.getAttribute('href'));
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  });
});